		if (!BLOCKS[id]?.breakable) return `${BLOCKS[id]?.name ?? "that"} cannot be mined`;
		const far = this.reachOk(x, y, z);
		if (far) return far;
		const eye = this.body.eyePosition();
		const dir = new THREE.Vector3(x + .5 - eye.x, y + .5 - eye.y, z + .5 - eye.z);
