	const eye = agent.eyePosition();
	const dir = new THREE.Vector3(Math.sin(agent.heading), -.25, Math.cos(agent.heading));
	const hit = raycastVoxel((a, b, c) => w.getBlock(a, b, c), (id) => id !== B.air && id !== B.water, eye, dir, 6);
	const pos = cellOf(agent.pos);
